"""Underline all headlines in the unpacked quarterly_report.docx.

Headlines are the report section lines written entirely in uppercase
(e.g., EXECUTIVE SUMMARY, RISK FACTORS). Since every paragraph in this
document uses plain formatting (no Heading styles), headlines are detected
by content: non-empty paragraph text consisting solely of uppercase letters,
digits, and whitespace, with at least one letter. Body text, bullet items,
table rows, the separator line, and blanks never match.
"""

import io
import re
import sys

try:
    from defusedxml import minidom
except ImportError:  # pragma: no cover - stdlib fallback
    from xml.dom import minidom

DOC_PATH = "unpacked/word/document.xml"

# CT_RPr children that must appear AFTER w:u in the OOXML schema sequence.
AFTER_U = {
    "w:effect", "w:bdr", "w:shd", "w:fitText", "w:vertAlign",
    "w:rtl", "w:cs", "w:em", "w:lang", "w:eastAsianLayout",
    "w:specVanish", "w:oMath",
}


def visible_text(para):
    """Concatenate visible (non-deleted) text of a paragraph's runs."""
    parts = []
    for t in para.getElementsByTagName("w:t"):
        for child in t.childNodes:
            if child.nodeType == child.TEXT_NODE:
                parts.append(child.data)
    return "".join(parts)


def is_headline(text):
    s = text.strip()
    if not s:
        return False
    if not any(ch.isalpha() for ch in s):
        return False
    return all(ch.isupper() or ch.isdigit() or ch.isspace() for ch in s)


def find_rpr(run, dom):
    for child in run.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:rPr":
            return child
    rpr = dom.createElement("w:rPr")
    if run.firstChild:
        run.insertBefore(rpr, run.firstChild)
    else:
        run.appendChild(rpr)
    return rpr


def set_underline(run, dom):
    rpr = find_rpr(run, dom)
    for u in list(rpr.getElementsByTagName("w:u")):
        rpr.removeChild(u)
    u = dom.createElement("w:u")
    u.setAttribute("w:val", "single")
    anchor = None
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.tagName in AFTER_U:
            anchor = child
            break
    if anchor is not None:
        rpr.insertBefore(u, anchor)
    else:
        rpr.appendChild(u)


def main():
    with open(DOC_PATH, "rb") as f:
        dom = minidom.parse(f)

    body = dom.getElementsByTagName("w:body")
    if not body:
        print("ERROR: no w:body found", file=sys.stderr)
        sys.exit(1)

    underlined = []
    for para in body[0].getElementsByTagName("w:p"):
        text = visible_text(para)
        if not is_headline(text):
            continue
        runs = para.getElementsByTagName("w:r")
        if not runs:
            continue
        for run in runs:
            set_underline(run, dom)
        underlined.append(text.strip())

    if not underlined:
        print("ERROR: no headlines detected", file=sys.stderr)
        sys.exit(1)

    buf = io.StringIO()
    dom.writexml(buf)
    xml_str = buf.getvalue()
    xml_str = re.sub(
        r"^<\?xml[^>]*\?>",
        '<?xml version="1.0" encoding="ascii"?>',
        xml_str,
        count=1,
    )
    data = xml_str.encode("ascii", "xmlcharrefreplace")
    with open(DOC_PATH, "wb") as f:
        f.write(data)

    # Sanity: the result must still parse and the headline text must be unchanged.
