                   for p in check.getElementsByTagName("w:body")[0]
                   .getElementsByTagName("w:p")]
    missing = [t for t in underlined if t not in check_texts]
    if missing:
        print("ERROR: verification failed, missing: %s" % missing, file=sys.stderr)
        sys.exit(1)

    print("Underlined %d headline(s):" % len(underlined))
    for h in underlined:
        print("  - %s" % h)


