Headlines are identified structurally: paragraphs whose visible text contains
no lowercase letters and at least one letter (all-caps section titles such as
"EXECUTIVE SUMMARY"), excluding bulleted lines, table rules/rows, and empty
spacer paragraphs. The underlining is applied as <w:u w:val="single"/> on each
run's rPr, which Word renders as a single underline.
"""

import sys
from pathlib import Path

sys.path.insert(0, str(Path(".codex/skills/docx").resolve()))

from scripts.utilities import XMLEditor

EDITOR = XMLEditor("unpacked/word/document.xml")
dom = EDITOR.dom


def run_text(run):
    parts = []
    for t in run.getElementsByTagName("w:t"):
        if t.firstChild:
            parts.append(t.firstChild.data)
    return "".join(parts)


def para_text(p):
    return "".join(run_text(r) for r in p.getElementsByTagName("w:r"))


def is_headline(p):
    text = para_text(p).strip()
    if not text:
        return False
    if text.startswith("\u2022") or text.startswith("\u25aa"):
        return False
    # All-caps title: has letters but no lowercase characters
    return any(ch.isalpha() for ch in text) and not any(ch.islower() for ch in text)


def ensure_underline(run):
    rprs = run.getElementsByTagName("w:rPr")
    if rprs:
        rpr = rprs[0]
    else:
        rpr = dom.createElement("w:rPr")
        if run.firstChild:
            run.insertBefore(rpr, run.firstChild)
        else:
            run.appendChild(rpr)
    for u in rpr.getElementsByTagName("w:u"):
        if u.getAttribute("w:val") == "single":
            return
    u = dom.createElement("w:u")
    u.setAttribute("w:val", "single")
    # w:u sorts after sz/szCs in CT_RPr; existing rPr only holds rFonts/sz/szCs
    rpr.appendChild(u)


headlines = []
for p in dom.getElementsByTagName("w:p"):
    if is_headline(p):
        for r in p.getElementsByTagName("w:r"):
            ensure_underline(r)
        headlines.append(para_text(p).strip())

EDITOR.save()

# Verify every headline run now carries a single underline
ok = True
for p in dom.getElementsByTagName("w:p"):
    if is_headline(p):
        for r in p.getElementsByTagName("w:r"):
            rprs = r.getElementsByTagName("w:rPr")
            covered = False
            if rprs:
                for u in rprs[0].getElementsByTagName("w:u"):
                    if u.getAttribute("w:val") == "single":
                        covered = True
            if not covered:
                ok = False

print(f"Underlined {len(headlines)} headlines:")
for h in headlines:
    print(f"  - {h}")
print("Verification:", "PASS" if ok and headlines else "FAIL")
if not ok or not headlines:
    sys.exit(1)

