import xml.dom.minidom as minidom

W_NS = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"

# ECMA-376 run-property order (CT_RPr) so <w:u> is inserted schema-correctly.
RPR_ORDER = [
    "w:rStyle", "w:rFonts", "w:b", "w:bCs", "w:i", "w:iCs", "w:caps",
    "w:smallCaps", "w:strike", "w:dstrike", "w:outline", "w:shadow",
    "w:emboss", "w:imprint", "w:noProof", "w:snapToGrid", "w:vanish",
    "w:webHidden", "w:color", "w:spacing", "w:w", "w:kern", "w:position",
    "w:sz", "w:szCs", "w:highlight", "w:u", "w:effect", "w:bdr", "w:shd",
    "w:fitText", "w:vertAlign", "w:rtl", "w:cs", "w:em", "w:lang",
    "w:eastAsianLayout", "w:specVanish", "w:oMath",
]

EXPECTED_HEADLINES = {
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
}


def element_text(elem):
    """Concatenate non-whitespace text of element, recursing into children."""
    parts = []
    for node in elem.childNodes:
        if node.nodeType == node.TEXT_NODE:
            if node.data.strip():
                parts.append(node.data)
        elif node.nodeType == node.ELEMENT_NODE:
            parts.append(element_text(node))
    return "".join(parts)


def main():
    unpacked = sys.argv[1] if len(sys.argv) > 1 else "unpacked"
    docx_name = sys.argv[2] if len(sys.argv) > 2 else "quarterly_report.docx"
    xml_path = f"{unpacked}/word/document.xml"

    dom = minidom.parse(xml_path)
    bodies = dom.getElementsByTagName("w:body")
    if len(bodies) != 1:
        raise SystemExit(f"Expected one <w:body> in {xml_path}, got {len(bodies)}")
    body = bodies[0]

    # <w:u w:val="single"/> template parsed in the w namespace, then imported.
    template = minidom.parseString(
        '<w:u xmlns:w="{0}" w:val="single"/>'.format(W_NS)
    ).documentElement

    underlined = []
    for para in body.getElementsByTagName("w:p"):
        text = element_text(para).strip()
        # A headline here is a short standalone ALL-CAPS line (a section
        # title). Body copy, bullet rows and table rows contain lowercase
        # text and therefore never satisfy isupper().
        if not text or not text.isupper() or not any(c.isalpha() for c in text):
            continue
        underlined.append(text)
        for run in para.getElementsByTagName("w:r"):
            rprs = run.getElementsByTagName("w:rPr")
            if rprs:
                rpr = rprs[0]
            else:
                rpr = dom.createElement("w:rPr")
                if run.firstChild:
                    run.insertBefore(rpr, run.firstChild)
                else:
                    run.appendChild(rpr)
            if rpr.getElementsByTagName("w:u"):
                continue
            u = dom.importNode(template, True)
            u_rank = RPR_ORDER.index("w:u")
            anchor = None
            for child in rpr.childNodes:
                if (
                    child.nodeType == child.ELEMENT_NODE
                    and child.tagName in RPR_ORDER
                    and RPR_ORDER.index(child.tagName) > u_rank
                ):
                    anchor = child
                    break
            if anchor is not None:
                rpr.insertBefore(u, anchor)
            else:
                rpr.appendChild(u)

    found = set(underlined)
    if found != EXPECTED_HEADLINES:
        raise SystemExit(
            "Headline detection mismatch: "
            f"missing={sorted(EXPECTED_HEADLINES - found)} "
            f"unexpected={sorted(found - EXPECTED_HEADLINES)}"
        )

    with open(xml_path, "wb") as fh:
        fh.write(dom.toxml(encoding="ascii"))
    print(f"Underlined {len(underlined)} headlines in {docx_name}: "
          + ", ".join(sorted(underlined)))


if __name__ == "__main__":
    main()

