                    and RPR_ORDER.index(child.tagName) > u_rank
                ):
                    anchor = child
                    break
            if anchor is not None:
                rpr.insertBefore(u, anchor)
            else:
                rpr.appendChild(u)

    found = set(underlined)
    if found != EXPECTED_HEADLINES:
        raise SystemExit(
            "Headline detection mismatch: "
            f"missing={sorted(EXPECTED_HEADLINES - found)} "
            f"unexpected={sorted(found - EXPECTED_HEADLINES)}"
        )

    with open(xml_path, "wb") as fh:
        fh.write(dom.toxml(encoding="ascii"))
    print(f"Underlined {len(underlined)} headlines in {docx_name}: "
          + ", ".join(sorted(underlined)))


if __name__ == "__main__":
    main()
